/**
 * bundle.js — load the data bundle and derive the perceptual anchors.
 *
 * data/amoc_translate_bundle.json (schema v1.0.0, generated by NB06 of
 * amoc-thesis-pipeline) is the single source of truth: every value that ever
 * reaches the screen derives from it. Nothing here is hard-coded — all
 * anchors are computed from the bundle's own arrays (fidelity, Ch. 7).
 */

/** Fetch + parse the bundle JSON. Throws on HTTP failure. */
export async function loadBundle(url = '/data/amoc_translate_bundle.json') {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Bundle fetch failed: ${res.status} ${res.statusText} (${url})`);
  return res.json();
}

/**
 * Local meridional velocity ∝ dΨ/dz. Ψ is cumulative transport, not velocity:
 * the actual flow direction at a depth is the vertical derivative of the
 * streamfunction. Central finite differences, accounting for the non-uniform
 * depth spacing; edge-safe (one-sided at the boundaries). Identical to the
 * velocity() logic validated in viz1.
 */
export function velocity(prof, depth) {
  const n = depth.length;
  const v = new Array(n);
  for (let i = 0; i < n; i++) {
    const a = Math.max(0, i - 1), b = Math.min(n - 1, i + 1);
    const dz = depth[b] - depth[a];
    v[i] = dz > 0 ? (prof[b] - prof[a]) / dz : 0;
  }
  return v;
}

/**
 * Derive the anchors every scene shares, FROM THE BUNDLE ONLY.
 *
 * Flow regimes are bounded by VELOCITY sign changes (v ∝ dΨ/dz), NOT by the
 * Ψ zero-crossing. Ψ is cumulative transport; v is the local flow. Driving
 * motion by Ψ would be physically wrong twice over: every parcel above the
 * Ψ zero-crossing would move the same way (though the deep return flow is
 * already southward well above it), and parcels would be fastest where Ψ
 * peaks — exactly where the true velocity is zero. The Ψ zero-crossing
 * remains meaningful as the boundary between the upper and deep CELLS of
 * cumulative transport; vSign1/vSign2 bound the three local flow regimes
 * (northward → southward → abyssal northward).
 *
 * @param {object} pca  the bundle's `pca` block
 */
export function deriveAnchors(pca) {
  const depth = pca.depth_m;
  const mean = pca.mean_profile;
  const n = depth.length;

  // P1 — intensity: peak northward transport of the mean profile.
  let peakIdx = 0;
  for (let i = 1; i < n; i++) if (mean[i] > mean[peakIdx]) peakIdx = i;
  const peakSv = mean[peakIdx];
  const peakDepth = depth[peakIdx];

  // Depth where mean Ψ crosses zero below the peak (upper cell → deep cell).
  // Grid value = first level with Ψ ≤ 0; interp = linear zero-crossing.
  let psiZeroDepth = depth[n - 1];
  let psiZeroDepthInterp = depth[n - 1];
  for (let i = peakIdx + 1; i < n; i++) {
    if (mean[i] <= 0) {
      psiZeroDepth = depth[i];
      const f = mean[i - 1] / (mean[i - 1] - mean[i]);
      psiZeroDepthInterp = depth[i - 1] + f * (depth[i] - depth[i - 1]);
      break;
    }
  }

  // P2 — the three flow regimes, bounded by velocity sign changes (see above).
  const vMean = velocity(mean, depth);
  let vSign1 = depth[n - 1], vSign2 = depth[n - 1];
  for (let i = 1; i < n; i++) {            // first downward reversal: upper limb → deep return
    if (vMean[i - 1] > 0 && vMean[i] <= 0) { vSign1 = depth[i]; break; }
  }
  for (let i = n - 1; i > 1; i--) {        // deepest reversal: deep return → abyssal cell
    if (vMean[i] > 0 && vMean[i - 1] <= 0) { vSign2 = depth[i]; break; }
  }

  return {
    peakSv, peakDepth, peakIdx,
    psiZeroDepth, psiZeroDepthInterp,
    vSign1, vSign2,
    velocity: (prof) => velocity(prof, depth),
    varExplained: pca.var_explained,        // for the "PC1 alone 89.8%" caption
    cumulative2pc: pca.cumulative_2pc,      // for the "97.86%" caption
  };
}
